        ".@..@@.@@.@@@@.@@.@..@..@@@@@@@@@@.@.@.@@..@@@@@...@@.@.@@@@.@@..@@@@@.@@@@@@@@@@@@@@.@@@@@.@@@@.@.@..@@@..@@@.@@@@@@@@@@.@...@@.@@@@..@.",
        "@..@@@@@@...@@.@@@@@.@@.@@@@@@.@@@@.@@@.@.@.@.@@.@@@@..@...@@@.@...@@@@@@@@@@@@@@...@@@@..@@@@@@@@@@@@@..@.....@@.@.@@..@.@@@@..@@@@.@.@@",
