        "@@.@@..@@..@@@@.@@@...@@@.@@...@@@@@@@@@@@..@@@@........@@@@@@@@@@..@@@@@@.@@@@..@@@@@@..@@.@.@..@.@@...@@@@.@.@@@@@.@.@@@@@.@@.@@.@@..@.",
        "@@@@@@@@@@@@..@@@..@.@@..@.@.@.@@.@..@@@@@.@.@@@@.@.@@.@..@@@..@..@@@@@@...@.@@.@@.@@..@.@.@@.@..@@@@@@@@...@@@@@.@@.@@@.@@.@@@.@@@@@.@@@",
