        "@@@.@.@.@@...@@.@.@@@@@@@@.@@.@.@@@..@@@.@.@.@.@@@..@@@@@@..@@@@@@@.@..@.@.@@@@@@@@.@@.@..@.@@@@@@@.@@...@@..@@@@.@@.@.@.@.....@.@..@@@@.",
        "@.@@@.@@@.@@@@.@@@@..@.@@..@.@.@@@@@.@@@.@.@.@..@..@@@@@.@@..@@@@.@@.@@...@..@@.@@@@@..@@..@@@@@@@.@@@...@@..@..@@@.@@@@@@@..@@@@@@@@@@.@",
